import React, { useEffect } from "react";
import * as Yup from "yup";
import { useFormik } from "formik";
import { useDispatch, useSelector } from "react-redux";
import { useStateContext } from "../../contexts/ContextProvider";
import { Link, Navigate, useNavigate } from "react-router-dom";
import { loadUser, registerUser } from "../../redux/auth/actions";
import { toast, ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

import { Button, Input } from "@heroui/react";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";
import Loading from "../../components/Loading";


const Register = () => {
  const navigate = useNavigate();
  const moment = require("moment");
  const dispatch = useDispatch();
  const { currentColor } = useStateContext();
  const user = useSelector((state) => state.Auth.user);
  const errors = useSelector((state) => state.Auth.errors);
  const loading = useSelector((state) => state.Auth.loading);
  const created = useSelector((state) => state.Auth.created);
  const formik = useFormik({
    initialValues: {
      first_name: "",
      last_name: "",
      phone: "",
      email: "",
      national_id: "",
      password: "",
      confirm_password: "",
      date_of_birth: ''
    },

    validationSchema: Yup.object({
      date_of_birth: Yup.string().required().label("Date of birth"),
      first_name: Yup.string().required().label("First name"),
      last_name: Yup.string().required().label("Last name"),
      national_id: Yup.string().required().label("National ID"),
      phone: Yup.string().required().label("Phone"),
      email: Yup.string().email().required().label("Email"),
      password: Yup.string()
        .min(6, "Must be 6 characters or more")
        .required("Enter password")
        .label("Password"),
      confirm_password: Yup.string()
        .oneOf([Yup.ref("password"), null], "Passwords must match")
        .required("Confirm your password"),
    }),
    onSubmit: (values) => {
      let data = new FormData();

      data.append("first_name", values.first_name);
      data.append("last_name", values.last_name);
      data.append("national_id", values.national_id);
      data.append("email", values.email);
      data.append("phone", values.phone);
      data.append(
        "date_of_birth",
        moment(values.date_of_birth).format("YYYY-MM-DD")
      );
      data.append("country", values.country);
      data.append("region", values.region);
      data.append("password", values.password);

      // values.images.map((x) => {
      //   data.append("images", x);
      // });

      dispatch(registerUser(data));
    },
  });

  useEffect(() => {
    if (created && user) {
      navigate("/login");
    }
  }, [created, user]);

  useEffect(() => {
    if (errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);
  return (
    <div className="container m-auto bg-gray-100 ">
      <div className="m-5">
        <ToastContainer position="bottom-center" theme="colored" />
      </div>
      <div className="text-center py-5">
        <img
          style={{ color: currentColor }}
          className="mx-auto h-12 w-auto"
          src="https://tailwindui.com/img/logos/workflow-mark-indigo-600.svg"
          alt="Workflow"
        />
        <h2 className="mt-6 text-center text-3xl font-extrabold text-gray-900">
          Register now
        </h2>
        <div className="flex justify-center my-5">
          <p className="mr-2">Not registered?</p>
          <Link
            style={{ color: currentColor }}
            className="text-blue-500"
            to="/login"
          >
            Sign In
          </Link>
        </div>
      </div>
      <div className=" flex justify-center items-center bg-gray-100">
        {loading ? (
          <Loading loading={loading} />
        ) : (
          <form
            className="sm:w-6/12 w-full m-3   p-3 rounded bg-white"
            onSubmit={formik.handleSubmit}
          >
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              <div>
                <Input
                  id="first_name"
                  name="first_name"
                  type="first_name"
                  autoComplete="text"
                  required
                  onChange={formik.handleChange}
                  onBlur={formik.handleBlur}
                  value={formik.values.first_name}
                  floatLabelType="Auto"
                  placeholder="Enter first name"
                />
                {formik.touched.first_name && formik.errors.first_name ? (
                  <p className="text-red-600">{formik.errors.first_name}</p>
                ) : null}
              </div>
              <div>
                <Input
                  id="last_name"
                  name="last_name"
                  type="last_name"
                  autoComplete="text"
                  required
                  onChange={formik.handleChange}
                  onBlur={formik.handleBlur}
                  value={formik.values.last_name}
                  floatLabelType="Auto"
                  placeholder="Enter last name"
                />
                {formik.touched.last_name && formik.errors.last_name ? (
                  <p className="text-red-600">{formik.errors.last_name}</p>
                ) : null}
              </div>
              <div>
                <Input
                  id="phone"
                  name="phone"
                  type="phone"
                  autoComplete="text"
                  required
                  onChange={formik.handleChange}
                  onBlur={formik.handleBlur}
                  value={formik.values.phone}
                  floatLabelType="Auto"
                  placeholder="Enter phone number"
                />
                {formik.touched.phone && formik.errors.phone ? (
                  <p className="text-red-600">{formik.errors.phone}</p>
                ) : null}
              </div>
              <div>
                <Input
                  id="email"
                  name="email"
                  type="email"
                  autoComplete="email"
                  required
                  onChange={formik.handleChange}
                  onBlur={formik.handleBlur}
                  value={formik.values.email}
                  floatLabelType="Auto"
                  placeholder="Enter your email address"
                />
                {formik.touched.email && formik.errors.email ? (
                  <p className="text-red-600">{formik.errors.email}</p>
                ) : null}
              </div>

              <div>

                <DatePicker placeholderText="Select date of birth" name="date_of_birth" selected={formik.values.date_of_birth} onChange={(date) => formik.setFieldValue('date_of_birth', date)} />
                {/* <DatePicker
                  label="Date of birth"
                  value={formik.values.date_of_birth}
                  name="date_of_birth"
                  format="yyyy-MM-dd"
                  id="date_of_birth"
                  placeholder="Select date of birth"
                  onChange={formik.handleChange}
                  floatLabelType="Auto"
                /> */}


                {formik.touched.date_of_birth && formik.errors.date_of_birth ? (
                  <p className="text-red-600">{formik.errors.date_of_birth}</p>
                ) : null}
              </div>

              <div>
                <Input
                  id="national_id"
                  name="national_id"
                  type="national_id"
                  autoComplete="text"
                  required
                  onChange={formik.handleChange}
                  onBlur={formik.handleBlur}
                  value={formik.values.national_id}
                  floatLabelType="Auto"
                  placeholder="Enter national ID"
                />
                {formik.touched.national_id && formik.errors.national_id ? (
                  <p className="text-red-600">{formik.errors.national_id}</p>
                ) : null}
              </div>
              <div>
                <Input
                  id="password"
                  name="password"
                  type="password"
                  required
                  onChange={formik.handleChange}
                  onBlur={formik.handleBlur}
                  value={formik.values.password}
                  floatLabelType="Auto"
                  placeholder="Enter password"
                />
                {formik.touched.password && formik.errors.password ? (
                  <p className="text-red-600">{formik.errors.password}</p>
                ) : null}
              </div>
              <div>
                <Input
                  id="confirm_password"
                  name="confirm_password"
                  type="password"
                  required
                  onChange={formik.handleChange}
                  onBlur={formik.handleBlur}
                  value={formik.values.confirm_password}
                  floatLabelType="Auto"
                  placeholder="Confirm your password"
                />
                {formik.touched.confirm_password &&
                  formik.errors.confirm_password ? (
                  <p className="text-red-600">
                    {formik.errors.confirm_password}
                  </p>
                ) : null}
              </div>
            </div>
            <div className="text-center my-5">
              <Button
                style={{ backgroundColor: currentColor, color: "white" }}
                type="submit"
                className="btn w-full md:w-96 text-white"
              >
                Submit
              </Button>
            </div>
          </form>
        )}
      </div>
    </div>
  );
};

export default Register;
